-- ---------- Fonctions utilitaires (stock) ----------
CREATE OR REPLACE FUNCTION get_product_total_stock(product_variants JSONB)
RETURNS INTEGER AS $$
BEGIN
  RETURN (
    SELECT COALESCE(SUM((variant->>''quantity'')::integer), 0)
    FROM jsonb_array_elements(product_variants) AS variant
  );
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE OR REPLACE VIEW products_with_stock AS
SELECT p.*, get_product_total_stock(p.variants) AS total_stock,
  CASE WHEN get_product_total_stock(p.variants) = 0 THEN true ELSE false END AS show_promo_badge
FROM products p;

CREATE OR REPLACE FUNCTION check_variant_availability(p_product_id UUID, p_color TEXT, p_size TEXT, p_quantity INTEGER)
RETURNS BOOLEAN AS $$
DECLARE v_available INTEGER;
BEGIN
  SELECT COALESCE((variant->>''quantity'')::integer, 0) INTO v_available
  FROM products p, jsonb_array_elements(p.variants) AS variant
  WHERE p.id = p_product_id AND variant->>''color'' = p_color AND variant->>''size'' = p_size;
  RETURN v_available >= p_quantity;
END;
